const dishes=[{title:'Rich spices.<br><em>Real comfort.</em>',description:'Fragrant biryani, tender beef, and the kind of flavour that brings you back to the table.',image:3,name:'Beef biryani',price:500,alt:'Atlanta Cuisine beef biryani with fragrant rice'},{title:'A little warmth.<br><em>A lot of flavour.</em>',description:'Rich, flavour-packed beef curry. A familiar favourite, made for a satisfying lunch or an unhurried dinner.',image:13,name:'Beef curry',price:400,alt:'Beef curry with a serving of rice'},{title:'Golden bites.<br><em>Happy moments.</em>',description:'Bring your appetite for chicken, golden fries, and good conversation around the table.',image:15,name:'Chicken & fries',price:450,alt:'Chicken served with golden fries'},{title:'One more sip.<br><em>Stay a while.</em>',description:'Make a little room for something sweet. A creamy milkshake is a lovely way to finish your meal.',image:14,name:'Milkshake',price:350,alt:'Creamy chocolate milkshake'}];let current=0;const dots=[...document.querySelectorAll('.dots button')];function showDish(i){current=(i+dishes.length)%dishes.length;const d=dishes[current];document.querySelector('#dish-title').innerHTML=d.title;document.querySelector('#dish-description').textContent=d.description;document.querySelector('#hero-image').src=`assets/photo-${d.image}.webp`;document.querySelector('#hero-image').alt=d.alt;document.querySelector('#dish-name').textContent=d.name;document.querySelector('#dish-price').textContent=`KSh ${d.price}`;document.querySelector('#counter').textContent=`0${current+1} / 04`;dots.forEach((b,n)=>{b.classList.toggle('active',n===current);b.setAttribute('aria-pressed',String(n===current))})}document.querySelector('#prev').onclick=()=>showDish(current-1);document.querySelector('#next').onclick=()=>showDish(current+1);dots.forEach((b,i)=>b.onclick=()=>showDish(i));let startX;document.querySelector('.hero-art').addEventListener('touchstart',e=>startX=e.changedTouches[0].clientX,{passive:true});document.querySelector('.hero-art').addEventListener('touchend',e=>{const diff=e.changedTouches[0].clientX-startX;if(Math.abs(diff)>45)showDish(current+(diff<0?1:-1))},{passive:true});
const menus={beef:{image:13,alt:'Beef curry served with rice',items:[['Beef curry',400],['Goat curry',550],['Stir-fried beef',450],['Stir-fried goat',550],['Beef biryani',500],['Beef pilau',350],['Beef samosa',50]]},chicken:{image:15,alt:'Chicken with fries',items:[['Chicken curry',450],['Stir-fried chicken',450],['Chicken pilau',450],['¼ fried chicken & chips',450],['Chicken biryani',550],['5 chicken wings & fries',450]]},fish:{image:10,alt:'A meal at Atlanta Cuisine',items:[['Whole tilapia wet fry',500],['Whole tilapia dry fry',500],['Pan-fried fish fillet',450]]},sides:{image:4,alt:'Chips masala with fresh salad',items:[['Spaghetti',400],['Maharagwe ya nazi',250],['Stir-fried liver (maini)',380],['Stir-fried matumbo',380],['Chips masala',250],['Bhajia',300],['Chips',200],['Rolex',150]]},drinks:{image:14,alt:'Chocolate milkshake',items:[['Spiced African tea',100],['Dawa',200],['Nescafé coffee (white)',150],['Hibiscus',150],['Milkshake',350],['Fresh juice',250],['Mocktail',250]]}};const tabs=[...document.querySelectorAll('[role=tab]')];function selectMenu(category){const data=menus[category];document.querySelector('#menu-items').innerHTML=data.items.map(([name,price],i)=>`<div class="menu-item"><small>${String(i+1).padStart(2,'0')}</small><h3>${name}</h3><span class="price">${price}</span></div>`).join('');document.querySelector('#menu-items').setAttribute('aria-labelledby',`tab-${category}`);document.querySelector('#menu-photo').src=`assets/photo-${data.image}.webp`;document.querySelector('#menu-photo').alt=data.alt;tabs.forEach(t=>{const active=t.dataset.category===category;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1})}tabs.forEach((t,i)=>{t.onclick=()=>selectMenu(t.dataset.category);t.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();selectMenu(tabs[n].dataset.category)}}});selectMenu('beef');const toggle=document.querySelector('.nav-toggle');toggle.onclick=()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');document.querySelector('nav').classList.toggle('open',open)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');document.querySelector('nav').classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){toggle.click();toggle.focus()}});document.querySelector('#year').textContent=new Date().getFullYear();
